 "SERVICE_SYNOPSES": {
  "salinity-reader": "Reads conductivity and temperature for every tank.",
  "alkalinity-reader": "Reads alkalinity, calcium and pH for the reef systems.",
  "nutrient-reader": "Reads nitrate and phosphate and compares them with the last seven nights.",
  "chemistry-compiler": "Writes the overnight log and routes any out-of-range reading to the morning crew.",
  "log-reader": "Reads the feeding log and groups feeds by exhibit.",
  "diet-reader": "Reads each exhibit's diet plan and what was due today.",
  "feeding-compiler": "Matches feeds to the plan and writes the daily ledger.",
  "roster-profiler": "Reads the roster and last week's memo and decides what to look at first.",
  "behavior-scout": "Reads the keeper notes for changes in behaviour: hiding, appetite, aggression.",
  "feeding-scout": "Reads the week's feeding ledgers for refusals and missed feeds.",
  "photo-scout": "Reads the photo survey for visible change: colour, fins, bell margins.",
  "water-scout": "Pulls the week's chemistry logs and marks any drift.",
  "image-reader": "Delegate: reads one photo set and describes what changed since last week.",
  "husbandry-compiler": "Writes the weekly memo: flags first, then the steady exhibits, then actions with owners.",
  "coral-scout": "Scans the approved suppliers for wishlist corals.",
  "fish-scout": "Scans the approved suppliers for wishlist fish, captive-bred first.",
  "drygoods-scout": "Scans for food, salt mix and filter media against the reorder list.",
  "order-compiler": "Writes the shortlist for the curator to approve.",
  "context-profiler": "Reads the brief and the sources and decides what each scout should look for.",
  "scout-one": "Reads the first source set.",
  "scout-two": "Reads the second source set.",
  "scout-three": "Reads the third source set.",
  "draft-compiler": "Writes the draft from the scouts' findings.",
  "scan-a": "Scans the first quarter of the watchlist.",
  "scan-b": "Scans the second quarter.",
  "scan-c": "Scans the third quarter.",
  "scan-d": "Scans the last quarter.",
  "shortlist-compiler": "Writes the shortlist from the four scans.",
  "reading-check": "Reads the feed and checks it against tonight's thresholds.",
  "alert-compiler": "Writes the alert, or a one-line all clear.",
  "plan-reader": "Reads the plan for what was due.",
  "tracker-compiler": "Matches the log to the plan and writes the tracker entry.",
  "run-sampler": "Picks a sample of recent runs across the fleet.",
  "contract-check": "Re-reads each sampled run against its contract.",
  "sweep-compiler": "Writes the sweep report."
 },
 "ENSURES_GIST": {
  "salinity-reader": "salinity and temperature per tank, with the previous night beside it",
  "alkalinity-reader": "alkalinity, calcium and pH per reef tank",
  "nutrient-reader": "nitrate and phosphate per tank, with a seven-night trend",
  "chemistry-compiler": "one line per tank; every flag shows its value and its range",
  "log-reader": "feeds per exhibit with amounts and refusals",
  "diet-reader": "what each exhibit was due today",
  "feeding-compiler": "every planned feed matched or listed as missed",
  "roster-profiler": "a watchlist of exhibits, with the reason each is on it",
  "behavior-scout": "behaviour changes per exhibit, each with the note it came from",
  "feeding-scout": "refusals and missed feeds per exhibit",
  "photo-scout": "visible changes per exhibit, each with its photo",
  "water-scout": "drift per tank with the nights it lasted",
  "image-reader": "one description per photo",
  "husbandry-compiler": "one section per exhibit; every flag cites its evidence; actions have owners",
  "coral-scout": "in-stock corals with price, size and quarantine terms",
  "fish-scout": "in-stock fish with origin, price and quarantine terms",
  "drygoods-scout": "dry goods with price per unit and ship date",
  "order-compiler": "a shortlist within budget, every line dated and linked"
 },
